namespace Ordering;

/// <summary>Coordinates product return processing, refund handling, and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnProcessingService _returnProcessing;
    private readonly RefundService _refunds = new();
    private readonly RestockInventory _inventory = new();

    public ReturnsHandler()
    {
        _returnProcessing = new ReturnProcessingService(_inventory);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returnProcessing.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _returnProcessing.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refunds.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refunds.Log(order, amount);

    public int Restock(Order order) =>
        _inventory.Restock(order);
}

internal sealed class ReturnProcessingService
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);
    private readonly RestockInventory _inventory;

    public ReturnProcessingService(RestockInventory inventory)
    {
        _inventory = inventory;
    }

    public string Process(Order order, Customer customer)
    {
        var validationResult = ValidateRequest(order, customer);
        if (validationResult is not null)
            return validationResult;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _inventory.AddPending(line.Sku, line.Quantity);
        }

        if (!_inventory.HasPendingEntries)
            return "no returnable lines";

        _processedReferences.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReferences.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;

            return true;
        }

        return false;
    }

    private string? ValidateRequest(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReferences.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        return null;
    }
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _log = new();

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
            refund += ComputeLineRefund(line.Quantity);

        if (_log.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _log.Add(FormatLogEntry(order.Reference, amount));
        if (_log.Count > 500 && amount > 1000m)
            _log.Add($"{order.Reference}:flag");
    }

    private static decimal ComputeLineRefund(int quantity)
    {
        if (quantity <= 0)
            return 0m;
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;
        if (quantity > 1)
            return quantity * UnitRefund;

        return UnitRefund;
    }

    private string FormatLogEntry(string reference, decimal amount)
    {
        if (_log.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}

internal sealed class RestockInventory
{
    private readonly Dictionary<string, int> _pendingBySku = new(StringComparer.Ordinal);

    public bool HasPendingEntries => _pendingBySku.Count != 0;

    public void AddPending(string sku, int quantity)
    {
        _pendingBySku[sku] = _pendingBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (!IsEligible(line))
                continue;

            var sku = line.Sku;
            if (_pendingBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _pendingBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _pendingBySku[sku] = line.Quantity / 2;
            }
            else
            {
                _pendingBySku[sku] = line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }

    private static bool IsEligible(OrderLine line) =>
        line.Quantity > 0 &&
        line.Quantity <= 100 &&
        !string.IsNullOrEmpty(line.Sku);
}
